import {validatePaper} from './literature-model.mjs';
export const backupLimit=50*1024*1024;
const groups=['projects','drafts','literature','reports','tasks'];
const limits={projects:1000,drafts:1000,literature:200,reports:500,tasks:100};
const object=v=>v&&typeof v==='object'&&!Array.isArray(v);
function guardTree(v,depth=0){if(depth>32)throw Error('备份结构过深。');if(typeof v==='number'&&!Number.isFinite(v))throw Error('备份包含无效数值。');if(typeof v==='string'&&v.length>5000000)throw Error('备份单项内容过大。');if(Array.isArray(v)){if(v.length>20000)throw Error('备份单项列表过长。');v.forEach(x=>guardTree(x,depth+1));}else if(object(v)){for(const [key,value]of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(key))throw Error('备份包含不支持的字段。');guardTree(value,depth+1);}}}
const validId=v=>(typeof v==='string'&&v.trim()&&v.length<=200)||(typeof v==='number'&&Number.isSafeInteger(v));
function validateReport(r){if(r.algorithm!=='local-exact-1.0.0'||r.complete!==true||!Array.isArray(r.sections)||!r.sections.length||!Array.isArray(r.sources))throw Error('仅支持完整的 PaperKnow 本地比对报告。');for(const field of ['totalChars','similarChars','uncitedChars','sourceCount','ratio','uncitedRatio'])if(typeof r[field]!=='number'||r[field]<0||!Number.isFinite(r[field]))throw Error('报告统计字段无效。');if(r.ratio>1||r.uncitedRatio>1)throw Error('报告比例无效。');const ids=new Set();for(const s of r.sources){if(!validId(s.id)||typeof s.title!=='string'||typeof s.text!=='string'||(!Array.isArray(s.authors)||!s.authors.every(a=>typeof a==='string')))throw Error('报告来源材料无效。');if(s.url){let u;try{u=new URL(s.url);}catch{throw Error('报告来源链接无效。');}if(!['http:','https:'].includes(u.protocol))throw Error('报告来源链接仅支持 HTTP / HTTPS。');}ids.add(s.id);}for(const section of r.sections){if(!validId(section.id)||typeof section.title!=='string'||!Array.isArray(section.paragraphs)||typeof section.included!=='boolean')throw Error('报告章节无效。');for(const p of section.paragraphs){if(!validId(p.id)||typeof p.text!=='string'||!Array.isArray(p.matches)||!Array.isArray(p.ranges)||!Array.isArray(p.uncitedRanges))throw Error('报告段落无效。');const length=Array.from(p.text).length;for(const range of [...p.ranges,...p.uncitedRanges,...p.matches.flatMap(m=>[m.range,...(Array.isArray(m.excludedRanges)?m.excludedRanges:[])])])if(!Array.isArray(range)||range.length!==2||!range.every(Number.isInteger)||range[0]<0||range[1]<range[0]||range[1]>length)throw Error('报告字符区间无效。');for(const m of p.matches){const source=r.sources.find(s=>s.id===m.sourceId);if(!ids.has(m.sourceId)||!Array.isArray(m.sourceRange)||m.sourceRange.length!==2||!m.sourceRange.every(Number.isInteger)||m.sourceRange[0]<0||m.sourceRange[1]>Array.from(source.text).length||m.sourceRange[1]<m.sourceRange[0]||!Array.isArray(m.excludedRanges))throw Error('报告对照区间无效。');}}}return r;}
export function validateBackup(input){if(!object(input)||input.format!=='paperknow-workspace-backup'||input.version!==1)throw Error('请选择 PaperKnow 工作空间备份 JSON（版本 1）。');guardTree(input);const result={};for(const key of groups){const rows=input[key]??[];if(!Array.isArray(rows)||rows.length>limits[key])throw Error(`${key} 列表无效或超出支持数量。`);const ids=new Set();result[key]=rows.map(raw=>{if(!object(raw)||!validId(raw.id)||ids.has(String(raw.id)))throw Error(`${key} 存在无效或重复记录编号。`);ids.add(String(raw.id));if(key==='literature')return validatePaper(raw);if(key==='reports')return validateReport(raw);if(key==='projects'&&(typeof raw.name!=='string'||!raw.name.trim()))throw Error('项目名称无效。');if(key==='drafts'){if(typeof raw.title!=='string'||typeof raw.tool!=='string'||(raw.text!==undefined&&typeof raw.text!=='string'))throw Error('成果内容无效。');const html=String(raw.html||'').replace(/<[^>]*>/g,tag=>/^<\/?(?:p|h[1-6]|strong|em|b|i|ul|ol|li|br)\s*\/?\s*>$/i.test(tag)?tag:'');return {...raw,html};}return raw;});}result.profile=object(input.profile)?{name:String(input.profile.name||'研究者').slice(0,20),degree:String(input.profile.degree||''),major:String(input.profile.major||'').slice(0,100)}:null;result.preferences=object(input.preferences)?input.preferences:null;result.moreFavorites=Array.isArray(input.moreFavorites)?[...new Set(input.moreFavorites.filter(id=>['posting','resume','translation'].includes(id)))]:[];return result;}
export function planMerge(current,incoming){const merged={},summary=[];for(const key of groups){const existing=current[key]||[],ids=new Set(existing.map(x=>String(x.id))),added=incoming[key].filter(x=>!ids.has(String(x.id)));merged[key]=[...existing,...added];if(merged[key].length>limits[key])throw Error(`合并后的 ${key} 数量超出支持范围，请分批整理材料。`);summary.push({key,added:added.length,skipped:incoming[key].length-added.length});}const projectIds=new Set(merged.projects.map(p=>String(p.id)));const orphaned=[...incoming.drafts,...incoming.literature,...incoming.reports].filter(r=>r.projectId&&!projectIds.has(String(r.projectId))).length;return {merged,summary,orphaned};}
export const backupLabels={projects:'项目',drafts:'成果草稿',literature:'文献与笔记',reports:'比对报告',tasks:'任务记录'};
